import type { CountryPack } from './schema.js';
import { BUILT_IN_CLIENT_PACKS } from './client-packs.generated.js';

/**
 * The browser's view of the country packs (`@trustwork/country-packs/client`). Client components need a pack's names,
 * currency, formats, default language, primary identifier label and subdivision list, never its facets, sources or
 * verification notes (the US pack alone is about 200 KB of JSON, most of it state facts). This entry therefore carries
 * only that v1 subset (`ClientPack`) of the built-in packs, from `client-packs.generated.ts` (regenerated by
 * `npm run generate:client -w @trustwork/country-packs`; a test fails when it drifts from the pack files), and imports
 * no validator, no facet schema and no country dataset. Facts stay on the server: `@trustwork/country-packs`.
 *
 * On the server the full registry mirrors every install into this one (`installPacks` in `registry.ts`), so code shared
 * by server and client components sees the deployment's packs on both sides. In the browser the registry holds the
 * built-in summaries plus what the server hands over for the visitor's country (a data-directory pack or the generic
 * profile of a country without a pack, `LocaleProvider`). Every pack installed here was validated by the server.
 */

export type ClientRegion = Pick<CountryPack['regions'][number], 'code' | 'name' | 'kind' | 'parent'>;

export type ClientPack = Pick<CountryPack, 'code' | 'name' | 'enabled' | 'locales' | 'defaultLocale' | 'currency' | 'secondaryCurrencies' | 'formats' | 'legalEntityTypes' | 'address'> & {
  registrationIdentifier: Pick<CountryPack['registrationIdentifier'], 'kind' | 'label' | 'pattern' | 'example'>;
  regions: ClientRegion[];
};

/** The v1 subset of a pack that the browser may receive: no facets, sources, notes, verification or data-residency facts. */
export function toClientPack(pack: ClientPack): ClientPack {
  const id = pack.registrationIdentifier;
  return {
    code: pack.code,
    name: pack.name,
    enabled: pack.enabled,
    locales: pack.locales,
    defaultLocale: pack.defaultLocale,
    currency: pack.currency,
    secondaryCurrencies: pack.secondaryCurrencies,
    formats: pack.formats,
    registrationIdentifier: { kind: id.kind, label: id.label, pattern: id.pattern, example: id.example },
    legalEntityTypes: pack.legalEntityTypes,
    regions: pack.regions.map((r) => ({ code: r.code, name: r.name, kind: r.kind, ...(r.parent ? { parent: r.parent } : {}) })),
    address: pack.address,
  };
}

export { BUILT_IN_CLIENT_PACKS };

export const FALLBACK_LOCALE = 'en';
/** Every locale a built-in pack lists, plus the engine fallback; `ru` is optional and never a default. The languages a deployment offers are configuration (`@trustwork/config`). */
export const ALL_LOCALES: readonly string[] = [...new Set([FALLBACK_LOCALE, ...BUILT_IN_CLIENT_PACKS.flatMap((p) => p.locales)])];

export function isLocale(value: string): boolean {
  return ALL_LOCALES.includes(value);
}

let active: readonly ClientPack[] = BUILT_IN_CLIENT_PACKS;
let byCode = new Map(active.map((p) => [p.code, p]));

/** Every active pack summary: the built-in ones, then the installed ones (a pack of the same code replaces the built-in). */
export function clientPacks(): readonly ClientPack[] {
  return active;
}

export function getClientPack(code: string): ClientPack | null {
  return byCode.get(code.toUpperCase()) ?? null;
}

/** Makes these summaries active next to the built-in ones (replacing earlier installs), reduced to the client subset. */
export function installClientPacks(extra: readonly ClientPack[]): void {
  const merged = new Map(BUILT_IN_CLIENT_PACKS.map((p) => [p.code, p]));
  for (const pack of extra) merged.set(pack.code, toClientPack(pack));
  active = [...merged.values()];
  byCode = new Map(active.map((p) => [p.code, p]));
}

/** Picks a localized string: the locale, then the engine fallback, then the first value present. */
export function pick(text: Record<string, string>, locale: string): string {
  return text[locale] ?? text[FALLBACK_LOCALE] ?? Object.values(text)[0] ?? '';
}

export function regionName(pack: Pick<ClientPack, 'regions'>, code: string, locale: string): string {
  const region = pack.regions.find((r) => r.code === code);
  return region ? pick(region.name, locale) : code;
}

type CurrencyMeta = ClientPack['currency'];

/** Minor-unit digits and symbol of any ISO 4217 code from `Intl` (packs state theirs explicitly). */
export function currencyMeta(code: string): CurrencyMeta {
  try {
    const format = new Intl.NumberFormat('en', { style: 'currency', currency: code });
    const digits = format.resolvedOptions().maximumFractionDigits ?? 2;
    const symbol = format.formatToParts(1).find((part) => part.type === 'currency')?.value ?? code;
    return { code, minorUnitDigits: digits, displayFractionDigits: digits, symbol };
  } catch {
    return { code, minorUnitDigits: 2, displayFractionDigits: 2, symbol: code };
  }
}

/** Money from contract minor units in the pack's currency, formatted for the locale (no hard-coded currency anywhere). */
export function formatMoney(minorUnits: string, currency: string, locale: string, options: { fractionDigits?: number | undefined } = {}): string {
  const pack = active.find((p) => p.currency.code === currency);
  const meta = pack?.currency ?? currencyMeta(currency);
  const digits = meta.minorUnitDigits;
  const major = Number(minorUnits) / 10 ** digits;
  const fraction = options.fractionDigits ?? meta.displayFractionDigits;
  return new Intl.NumberFormat(locale, { style: 'currency', currency, minimumFractionDigits: fraction, maximumFractionDigits: fraction }).format(major);
}

/** The fields of the country dataset (`countries.json`) a generic profile needs. */
export type GenericCountry = { code: string; name: Record<string, string>; currency: string | null; currencies: readonly string[]; callingCode: string | null; timeZones: readonly string[] };

/**
 * The client subset of the generic profile of a country without a contributed pack (`genericPack` in the full entry
 * builds the whole profile from the same fields; a test keeps both equal): no regions, a free-form identifier.
 */
export function genericClientPack(country: GenericCountry): ClientPack {
  // XXX is ISO 4217 "no currency": a country the dataset gives no currency is never assigned another country's.
  const currency = currencyMeta(country.currency ?? 'XXX');
  const callingCode = country.callingCode && /^\+\d{1,4}$/.test(country.callingCode) ? country.callingCode : '+0';
  return {
    code: country.code,
    name: country.name,
    enabled: true,
    locales: [...ALL_LOCALES],
    defaultLocale: FALLBACK_LOCALE,
    currency,
    secondaryCurrencies: country.currencies.filter((c) => c !== currency.code),
    formats: {
      timeZone: country.timeZones[0] ?? 'UTC',
      phone: { callingCode, nationalLength: 15, example: callingCode },
      postalCode: { pattern: '^.{0,16}$', example: '' },
    },
    registrationIdentifier: {
      kind: `${country.code}-REGNO`,
      label: { en: 'Company registration number', ru: 'Регистрационный номер компании' },
      pattern: '^[A-Za-z0-9 .\\-/]{2,32}$',
      example: '0000000',
    },
    legalEntityTypes: [{ code: 'other', name: { en: 'Legal entity', ru: 'Юридическое лицо' } }],
    regions: [],
    address: { lines: ['street', 'city', 'region', 'postalCode'], cityFirst: false },
  };
}
